.message-item {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    transition: background 0.1s;
}

.message-item.hovered {
    background: #f8f9fa;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

.message-author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #1a1a2e;
}

.message-time {
    font-size: 0.75rem;
    color: #868e96;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.5;
    color: #333;
    white-space: pre-wrap;
    word-break: break-word;
}

.message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
    margin-top: 0.35rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    background: #f0f0f5;
    border: 1px solid #dee2e6;
    border-radius: 12px;
    padding: 0.1rem 0.5rem;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.1s;
}

.reaction-badge:hover {
    background: #e0e0ea;
    border-color: #6c63ff;
}

.thread-link {
    display: inline-block;
    background: none;
    border: none;
    color: #6c63ff;
    font-size: 0.8rem;
    font-weight: 500;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.2rem;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.15rem;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.15rem 0.25rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.action-btn {
    background: none;
    border: none;
    font-size: 0.78rem;
    cursor: pointer;
    padding: 0.25rem 0.5rem;
    border-radius: 4px;
    color: #555;
    white-space: nowrap;
    transition: background 0.1s;
}

.action-btn:hover {
    background: #f0f0f5;
    color: #1a1a2e;
}

