arguments.file_text:
namespace sv_c163ebd4a8714659ac42f6c2efd972a9;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@using sv_c163ebd4a8714659ac42f6c2efd972a9

<div class="channel-item @(IsActive ? "active" : "")"
     @onclick="() => OnSelected.InvokeAsync(Channel.Id)"
     role="button">
    <div class="channel-info">
        <span class="channel-name"># @Channel.Name</span>
        <span class="channel-desc">@TruncateDescription(Channel.Description)</span>
    </div>
    @if (Channel.UnreadCount > 0)
    {
        <span class="unread-badge">@Channel.UnreadCount</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback<int> OnSelected { get; set; }

    private static string TruncateDescription(string desc) =>
        desc.Length > 40 ? string.Concat(desc.AsSpan(0, 37), "...") : desc;
}

.channel-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.6rem 0.75rem;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.1s;
    margin: 0 0.4rem;
}

.channel-item:hover {
    background: rgba(255, 255, 255, 0.1);
}

.channel-item.active {
    background: rgba(255, 255, 255, 0.18);
    font-weight: 600;
}

.channel-info {
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
    min-width: 0;
}

.channel-name {
    font-size: 0.9rem;
    color: #e0e0e8;
    font-weight: 500;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-item.active .channel-name {
    color: #fff;
    font-weight: 700;
}

.channel-desc {
    font-size: 0.72rem;
    color: #a0a0b4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    background: #6c63ff;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    border-radius: 10px;
    padding: 0.1rem 0.45rem;
    min-width: 1.3rem;
    text-align: center;
    flex-shrink: 0;
}

@using sv_c163ebd4a8714659ac42f6c2efd972a9

<div class="channel-sidebar">
    <h3 class="sidebar-title">Channels</h3>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelected="OnChannelSelected" />
        }
    </div>
</div>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int? ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

.channel-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    background: #1a1a2e;
    color: #e0e0e8;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #16162a;
    overflow: hidden;
}

.sidebar-title {
    padding: 1rem 1rem 0.6rem;
    font-size: 1rem;
    font-weight: 700;
    color: #fff;
    letter-spacing: 0.02em;
    margin: 0;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.25rem 0;
}

.channel-list::-webkit-scrollbar {
    width: 4px;
}

.channel-list::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.15);
    border-radius: 2px;
}

@using sv_c163ebd4a8714659ac42f6c2efd972a9

<div class="message-list">
    @if (HasMoreMessages)
    {
        <div class="load-more">
            <button class="btn btn-sm btn-outline-secondary" @onclick="OnLoadMore"
                    disabled="@IsLoading">
                @(IsLoading ? "Loading..." : "↑ Load older messages")
            </button>
        </div>
    }

    @foreach (var message in Messages)
    {
        <MessageItem Message="message"
                     ThreadSummary="GetThreadSummary(message.Id)"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />
    }
</div>

@code {
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public bool IsLoading { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ThreadSummary? GetThreadSummary(int messageId) =>
        ThreadSummaries.GetValueOrDefault(messageId);
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
