@using sv_c163ebd4a8714659ac42f6c2efd972a9

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <span class="root-author">@RootMessage.Author</span>
            <p class="root-content">@RootMessage.Content</p>
        </div>

        <div class="thread-divider">
            <span>@ThreadMessages.Count @(ThreadMessages.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in ThreadMessages)
            {
                <MessageItem Message="reply" OnReact="OnReact" />
            }
        </div>

        <MessageInput Placeholder="Reply in thread..."
                      ButtonText="Reply"
                      OnSubmit="OnSendReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
}

.thread-panel {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    border-left: 1px solid #dee2e6;
    background: #fafbfc;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #1a1a2e;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #868e96;
    padding: 0.2rem 0.4rem;
    border-radius: 4px;
    line-height: 1;
    transition: background 0.1s, color 0.1s;
}

.close-btn:hover {
    background: #f0f0f5;
    color: #1a1a2e;
}

.thread-root {
    padding: 0.75rem 1rem;
    background: #f0f0f5;
    border-bottom: 1px solid #dee2e6;
    flex-shrink: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #1a1a2e;
}

.root-content {
    margin: 0.25rem 0 0;
    font-size: 0.85rem;
    color: #333;
    line-height: 1.4;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-divider {
    text-align: center;
    padding: 0.4rem 0;
    font-size: 0.75rem;
    color: #868e96;
    border-bottom: 1px solid #eee;
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.25rem 0;
}

.thread-replies::-webkit-scrollbar {
    width: 4px;
}

.thread-replies::-webkit-scrollbar-thumb {
    background: #ccc;
    border-radius: 2px;
}

