arguments.file_text:
@page "/chat"
@using sv_c163ebd4a8714659ac42f6c2efd972a9
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="HandleChannelSelected" />

    <MessageArea Channel="selectedChannel"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 HasMoreMessages="hasMoreMessages"
                 IsLoading="isLoading"
                 OnSendMessage="HandleSendMessage"
                 OnOpenThread="HandleOpenThread"
                 OnReact="HandleReact"
                 OnLoadMore="HandleLoadMore" />

    @if (isThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     ThreadMessages="threadMessages"
                     OnSendReply="HandleSendReply"
                     OnClose="HandleCloseThread"
                     OnReact="HandleReact" />
    }
</div>

@code {
    private const int PageSize = 50;

    private List<Channel> channels = [];
    private int? selectedChannelId;
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private bool hasMoreMessages;
    private bool isLoading;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadMessages = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await HandleChannelSelected(channels[0].Id);
        }
    }

    private async Task HandleChannelSelected(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        threadSummaries = new();
        isThreadOpen = false;

        await LoadMessages(reset: true);
        await ChatService.MarkChannelReadAsync(channelId);

        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMessages(bool reset = false)
    {
        if (selectedChannelId is null) return;

        isLoading = true;
        var skip = reset ? 0 : messages.Count;
        var loaded = await ChatService.GetMessagesAsync(selectedChannelId.Value, skip, PageSize);

        if (reset)
            messages = loaded;
        else
            messages.InsertRange(0, loaded);

        hasMoreMessages = loaded.Count == PageSize;
        isLoading = false;
    }

    private async Task HandleLoadMore() => await LoadMessages();

    private async Task HandleSendMessage(string content)
    {
